      sha256 "6700d44c57a8f38db9ea1ccfb89edb5388c04b75fb371b43007912b6061274f9"
    end
    on_intel do
      url "https://github.com/diracdeltafunk/bibe-rs/releases/download/v0.1.0/bibers-0.1.0-universal-apple-darwin.tar.gz"
      sha256 "6700d44c57a8f38db9ea1ccfb89edb5388c04b75fb371b43007912b6061274f9"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/diracdeltafunk/bibe-rs/releases/download/v0.1.0/bibers-0.1.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "063e89ee0e02a58ab3b13db9d13615e142a0c6730c4ee0135d085c9e0192c948"
    end
    on_intel do
      url "https://github.com/diracdeltafunk/bibe-rs/releases/download/v0.1.0/bibers-0.1.0-x86_64-unknown-linux-musl.tar.gz"
